import itertools
def feats(g,i,j):
    H,W=len(g),len(g[0])
    v=g[i][j]
    orth=sum(g[a][b]==v for a,b in [(i-1,j),(i+1,j),(i,j-1),(i,j+1)] if 0<=a<H and 0<=b<W)
    diag=sum(g[a][b]==v for a,b in [(i-1,j-1),(i-1,j+1),(i+1,j-1),(i+1,j+1)] if 0<=a<H and 0<=b<W)
    edge = i in(0,H-1) or j in(0,W-1)
    # 2x2 blocks containing cell fully same color
    b2=0
    for a in range(i-1,i+1):
        for b in range(j-1,j+1):
            if 0<=a<H-1 and 0<=b<W-1:
                if all(g[a+dx][b+dy]==v for dx in(0,1) for dy in(0,1)): b2+=1
    return dict(v=v,orth=orth,diag=diag,edge=edge,b2=b2)
